"use strict";
(()=>{
 const $=id=>document.getElementById(id),language=navigator.language.toLowerCase().startsWith('zh')?'zh-CN':'en',labels=window.readerCatalogs[language],label=key=>labels[key]||key;
 let worker,sequence=0,pending=new Map(),selection,busy=false,protectedArchive=false,opened=false,generation=0;
 const urls=new Map();let urlBytes=0;const MAX_URL_BYTES=32*1024*1024;
 const decode64=text=>Uint8Array.from(atob(text),c=>c.charCodeAt(0));
 function status(key){$('standalone-status').textContent=key?label(key):'';}
 function fail(error){const key=error.message||'StandaloneReadFailed';status(key);if(opened)$('standalone-activity').textContent=label(key);}
 function setBusy(value){busy=value;for(const id of ['standalone-directory','standalone-compatible','standalone-open','standalone-refresh'])$(id).disabled=value;}
 function release(){generation++;worker?.terminate();worker=null;for(const request of pending.values()){clearTimeout(request.timer);request.reject(Error('cancelled'));}pending.clear();for(const item of urls.values())URL.revokeObjectURL(item.url);urls.clear();urlBytes=0;$('standalone-reader').srcdoc='';$('standalone-reader').hidden=true;$('standalone-toolbar').hidden=true;$('standalone-start').hidden=false;$('standalone-unlock').hidden=true;$('standalone-secret').value='';opened=false;selection=null;setBusy(false);}
 function request(action,args={}){if(!worker)return Promise.reject(Error('StandaloneChoose'));const id=++sequence;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(id);reject(Error('StandaloneTimeout'));},45000);pending.set(id,{resolve,reject,timer});worker.postMessage({id,action,args});});}
 function makeWorker(){const url=URL.createObjectURL(new Blob([decode64(standaloneWorkerSource)],{type:'text/javascript'}));worker=new Worker(url);URL.revokeObjectURL(url);worker.onmessage=e=>{let task=pending.get(e.data.id);if(!task)return;pending.delete(e.data.id);clearTimeout(task.timer);e.data.error?task.reject(Error(e.data.error)):task.resolve(e.data.result);};worker.onerror=()=>{for(const task of pending.values()){clearTimeout(task.timer);task.reject(Error('StandaloneReadFailed'));}pending.clear();};}
 function mime(path){let ext=path.split('.').at(-1).toLowerCase();return ({png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',bmp:'image/bmp',svg:'application/octet-stream',mp4:'video/mp4',webm:'video/webm',ogg:'audio/ogg',mp3:'audio/mpeg',m4a:'audio/mp4',wav:'audio/wav',txt:'text/plain'})[ext]||'application/octet-stream';}
 async function asset(path){if(urls.has(path)){let item=urls.get(path);urls.delete(path);urls.set(path,item);return item.url;}const epoch=generation,bytes=await request('asset',{path});if(epoch!==generation)throw Error('cancelled');const url=URL.createObjectURL(new Blob([bytes],{type:mime(path)}));while(urlBytes+bytes.length>MAX_URL_BYTES&&urls.size){const key=urls.keys().next().value,item=urls.get(key);URL.revokeObjectURL(item.url);urlBytes-=item.bytes;urls.delete(key);}urls.set(path,{url,bytes:bytes.length});urlBytes+=bytes.length;return url;}
 async function save(path,name){const epoch=generation,suggested=(name||path.split('/').at(-1)||'file').replace(/[\\/:*?"<>|]/g,'_');let writable=null;
  try{if(window.showSaveFilePicker){let handle=await showSaveFilePicker({suggestedName:suggested});writable=await handle.createWritable();const file=await request('file',{path});for(let ordinal=0;ordinal<file.Chunks;ordinal++){if(epoch!==generation)throw Error('cancelled');const bytes=await request('chunk',{path,ordinal});await writable.write(bytes);$('standalone-activity').textContent=label('StandaloneSaving').replace('{0}',Math.floor((ordinal+1)*100/Math.max(1,file.Chunks)));}await writable.close();writable=null;}else{const url=await asset(path),a=document.createElement('a');a.href=url;a.download=suggested;a.click();}$('standalone-activity').textContent=label('StandaloneSaved');}
  catch(error){if(writable)await writable.abort().catch(()=>{});if(error.name!=='AbortError')fail(error);}
 }
 const transport={page:(conversation,page)=>request('page',{conversation,page}),search:(text,cursor,reverse)=>request('search',{text,cursor,reverse}),reference:(conversation,reference)=>request('reference',{conversation,reference}),asset,save,stats:()=>request('stats'),error:fail};
 window.archiveTransport=transport;
 async function showReader(result){opened=true;$('standalone-secret').value='';$('standalone-unlock').hidden=true;$('standalone-start').hidden=true;$('standalone-toolbar').hidden=false;$('standalone-reader').hidden=false;$('standalone-activity').textContent=label('StandaloneReady');
  const frame=$('standalone-reader');frame.onload=()=>{if(!opened)return;const view=frame.contentWindow;view.archiveIndex=result.index;view.readerCatalogs=window.readerCatalogs;view.archiveTransport=transport;view.startStandaloneReader();};frame.srcdoc=new TextDecoder().decode(decode64(standaloneReaderDocument));
 }
 async function unlock(){if(busy)return;setBusy(true);status('StandaloneOpening');try{const result=await request('unlock',{secret:$('standalone-secret').value});await showReader(result);status('');}catch(error){fail(error);$('standalone-secret').select();}finally{setBusy(false);}}
 async function choose(args){release();selection=args;makeWorker();setBusy(true);status(args.files?'StandalonePreparingFiles':'StandaloneOpening');try{const info=await request('inspect',args);protectedArchive=info.protected;$('standalone-secret-label').textContent=label(info.mode==='direct-key'?'StandaloneDirectKey':'StandalonePassword');$('standalone-unlock').hidden=!info.protected;setBusy(false);if(!info.protected)await unlock();else{status('StandaloneUnlockHelp');$('standalone-secret').focus();}}catch(error){fail(error);}finally{setBusy(false);}}
 $('standalone-directory').onclick=async()=>{if(busy)return;try{const directory=await showDirectoryPicker({mode:'read'});await choose({directory});}catch(error){if(error.name!=='AbortError')fail(error);}};
 $('standalone-compatible').onclick=()=>$('standalone-files').click();$('standalone-files').onchange=async()=>{if($('standalone-files').files.length)await choose({files:Array.from($('standalone-files').files)});$('standalone-files').value='';};
 $('standalone-unlock').onsubmit=event=>{event.preventDefault();unlock();};$('standalone-lock').onclick=()=>{release();status('StandaloneLocked');};
 $('standalone-refresh').onclick=async()=>{if(busy)return;if(selection?.files){fail(Error('StandaloneReselect'));return;}setBusy(true);try{await showReader(await request('refresh'));}catch(error){fail(error);}finally{setBusy(false);}};
 for(const [id,key] of [['standalone-title','StandaloneTitle'],['standalone-help','StandaloneHelp'],['standalone-directory','StandaloneChoose'],['standalone-compatible','StandaloneCompatible'],['standalone-open','StandaloneOpen'],['standalone-license-label','StandaloneLicenses'],['standalone-refresh','StandaloneRefresh'],['standalone-lock','StandaloneLock']])$(id).textContent=label(key);
 $('standalone-directory').disabled=typeof window.showDirectoryPicker!=='function';if(!window.crypto?.subtle||typeof Worker==='undefined'||typeof WebAssembly==='undefined'){status('StandaloneUnsupported');$('standalone-directory').disabled=$('standalone-compatible').disabled=true;}else status('StandaloneChooseHelp');
 window.addEventListener('pagehide',()=>release());
})();
